CREATE TABLE IF NOT EXISTS usage_pricing(id bigserial PRIMARY KEY,provider_type text NOT NULL,provider text NOT NULL,model text NOT NULL DEFAULT '',operation text NOT NULL,unit_type text NOT NULL,unit_price numeric(30,12) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'USD',config_version text NOT NULL,active boolean NOT NULL DEFAULT true,effective_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_budgets(id bigserial PRIMARY KEY,scope_type text NOT NULL,scope_id text NOT NULL,period_key text NOT NULL DEFAULT 'lifetime',hard_cost_limit numeric(30,8),hard_usage_limit numeric(30,8),soft_cost_limit numeric(30,8),soft_usage_limit numeric(30,8),currency char(3) NOT NULL DEFAULT 'USD',state text NOT NULL DEFAULT 'ACTIVE',config_version text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_reservations(id text PRIMARY KEY,job_id text NOT NULL REFERENCES forge_jobs(id),project_id text REFERENCES projects(id),episode_id text REFERENCES episodes(id),provider_type text NOT NULL,provider text NOT NULL,model text,operation text NOT NULL,attempt integer NOT NULL,estimated_units numeric(30,8) NOT NULL DEFAULT 0,estimated_cost numeric(30,8) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'USD',status text NOT NULL DEFAULT 'HELD',terminal_reason text,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),settled_at timestamptz);
CREATE TABLE IF NOT EXISTS usage_events(id text PRIMARY KEY,event_key text NOT NULL UNIQUE,job_id text REFERENCES forge_jobs(id),provider_run_id text REFERENCES provider_runs(id),project_id text REFERENCES projects(id),episode_id text REFERENCES episodes(id),stage text,provider_type text NOT NULL,provider text NOT NULL,model text,operation text NOT NULL,execution_attempt integer NOT NULL DEFAULT 1,retry_count integer NOT NULL DEFAULT 0,input_artifact_refs jsonb NOT NULL DEFAULT '[]'::jsonb,output_artifact_refs jsonb NOT NULL DEFAULT '[]'::jsonb,duration_ms bigint,input_bytes bigint,output_bytes bigint,usage_units numeric(30,8) NOT NULL DEFAULT 0,normalized_cost_units numeric(30,8) NOT NULL DEFAULT 0,estimated_cost numeric(30,8),actual_cost numeric(30,8),currency char(3) NOT NULL DEFAULT 'USD',outcome text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_regions(region_id text PRIMARY KEY,display_name text NOT NULL,status text NOT NULL DEFAULT 'READY',health_score integer NOT NULL DEFAULT 100,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO forge_regions(region_id,display_name) VALUES('primary','Primary region') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS forge_control_plane_state(id boolean PRIMARY KEY DEFAULT true,active_region_id text NOT NULL REFERENCES forge_regions(region_id),routing_epoch bigint NOT NULL DEFAULT 1,fencing_token bigint NOT NULL DEFAULT 1,mode text NOT NULL DEFAULT 'ACTIVE');
INSERT INTO forge_control_plane_state(id,active_region_id) VALUES(true,'primary') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS forge_tenant_residency_policies(tenant_id text PRIMARY KEY,home_region_id text NOT NULL REFERENCES forge_regions(region_id),active_region_id text NOT NULL REFERENCES forge_regions(region_id),allowed_region_ids jsonb NOT NULL DEFAULT '["primary"]'::jsonb,routing_epoch bigint NOT NULL DEFAULT 1);
CREATE OR REPLACE FUNCTION forge_job_fence_valid(p_tenant text,p_region text,p_epoch bigint,p_token bigint,p_worker_region text) RETURNS boolean AS $$ BEGIN RETURN COALESCE(p_region,'primary')=COALESCE(p_worker_region,'primary') AND COALESCE(p_epoch,1)=1 AND COALESCE(p_token,1)=1; END; $$ LANGUAGE plpgsql STABLE;
CREATE TABLE IF NOT EXISTS forge_events(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),project_id text REFERENCES projects(id),event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_event_subscriptions(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),project_id text REFERENCES projects(id),endpoint_url text NOT NULL,event_types text[] NOT NULL DEFAULT '{}',ordered boolean NOT NULL DEFAULT false,rate_limit_per_second integer NOT NULL DEFAULT 10,max_concurrency integer NOT NULL DEFAULT 4,active boolean NOT NULL DEFAULT true,endpoint_config_ref text,delivery_epoch bigint NOT NULL DEFAULT 1,active_key_id text,circuit_state text NOT NULL DEFAULT 'CLOSED',circuit_failures integer NOT NULL DEFAULT 0,circuit_opened_until timestamptz,max_attempts integer NOT NULL DEFAULT 5,governance_decision_id text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_event_deliveries(id text PRIMARY KEY,event_id text NOT NULL REFERENCES forge_events(id),subscription_id text NOT NULL REFERENCES forge_event_subscriptions(id),tenant_id text NOT NULL REFERENCES tenants(id),status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_event_delivery_attempts(id bigserial PRIMARY KEY,delivery_id text NOT NULL REFERENCES forge_event_deliveries(id) ON DELETE CASCADE,attempt integer NOT NULL,status text NOT NULL,http_status integer,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_rate_limit_policies(id bigserial PRIMARY KEY,scope_type text NOT NULL,tenant_id text,project_id text,plan_version text NOT NULL,route_class text NOT NULL,method text NOT NULL,sustained_rate numeric(20,6) NOT NULL DEFAULT 120,burst_capacity numeric(20,6) NOT NULL DEFAULT 60,concurrency_limit integer NOT NULL DEFAULT 32,priority integer NOT NULL DEFAULT 100,enforcement_mode text NOT NULL DEFAULT 'ENFORCE',fail_mode text NOT NULL DEFAULT 'FAIL_CLOSED',effective_version bigint NOT NULL DEFAULT 1,trusted_bypass_scope text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,active boolean NOT NULL DEFAULT true,updated_by text NOT NULL DEFAULT 'system',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_rate_limit_policies_scope_idx ON forge_rate_limit_policies(scope_type,tenant_id,project_id,route_class,method,active,effective_version DESC);
CREATE TABLE IF NOT EXISTS forge_rate_limit_policy_history(id bigserial PRIMARY KEY,policy_id bigint NOT NULL REFERENCES forge_rate_limit_policies(id) ON DELETE CASCADE,tenant_id text,project_id text,effective_version bigint NOT NULL,snapshot jsonb NOT NULL,actor text NOT NULL,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_rate_limit_buckets(bucket_key text PRIMARY KEY,policy_id bigint NOT NULL REFERENCES forge_rate_limit_policies(id) ON DELETE CASCADE,scope_type text NOT NULL,tenant_id text,project_id text,route_class text NOT NULL,method text NOT NULL,tokens numeric(30,8) NOT NULL DEFAULT 0,last_refill_at timestamptz NOT NULL DEFAULT now(),active_concurrency integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_rate_limit_buckets_scope_idx ON forge_rate_limit_buckets(tenant_id,project_id,route_class,method);
CREATE TABLE IF NOT EXISTS forge_rate_limit_requests(request_key text PRIMARY KEY,tenant_id text,project_id text,method text NOT NULL,route_class text NOT NULL,outcome text NOT NULL,token_cost numeric(30,8) NOT NULL DEFAULT 1,retry_after_seconds integer NOT NULL DEFAULT 0,policy_versions jsonb NOT NULL DEFAULT '[]'::jsonb,policy_ids jsonb NOT NULL DEFAULT '[]'::jsonb,started_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS forge_rate_limit_audit(id bigserial PRIMARY KEY,tenant_id text,project_id text,request_key text,method text NOT NULL,route_class text NOT NULL,outcome text NOT NULL,reason text,policy_versions jsonb NOT NULL DEFAULT '[]'::jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
